const AsciiString &UpgradeMaskType::getFirstUpgradeName() const
{
	for (Int bit = 0; bit < 0x400; ++bit)
	{
		if (m_bits[(UnsignedInt)bit >> 5] & (1 << (bit & 31)))
		{
			const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgradeByMaskIndex(bit);
			if (upgrade)
				return upgrade->m_name;
		}
	}
	return AsciiString::TheEmptyString;
}

